ScopedTemplateMemberValueDependencyCollectionPause::
ScopedTemplateMemberValueDependencyCollectionPause(bool active)
  : active_(active)
{
  if(active_) {
    ++template_member_value_dependency_collection_pause_depth();
  }
}

ScopedTemplateMemberValueDependencyCollectionPause::
~ScopedTemplateMemberValueDependencyCollectionPause()
{
  if(active_) {
    --template_member_value_dependency_collection_pause_depth();
  }
}

